css
body {
  animation: cyberpsycho-glitch 1s linear infinite;
  filter: contrast(150%) hue-rotate(10deg) saturate(200%);
}

@keyframes cyberpsycho-glitch {
  0% { transform: translate(0) skew(0deg); filter: drop-shadow(-2px 0 red); }
  10% { transform: translate(-2px, 2px) skew(-1deg); }
  20% { transform: translate(2px, -1px) skew(2deg); filter: drop-shadow(2px 0 blue); }
  30% { transform: translate(0); }
  90% { transform: translate(1px, -2px); }
  100% { transform: translate(-1px, 2px) skew(1deg); }
}
